/**
 * values that may appear in "type". Equals SchemaObjectType
 */
const possibleSchemaTypes = new Set([
  'integer',
  'number',
  'string',
  'boolean',
  'object',
  'strictObject',
  'null',
  'array',
]);

export const predefinedZodFormats = new Set([
  'date',
  'time',
  'date-time',
  'email',
  'uri',
  'hostname',
  'uuid',
]);

type ResolvedZodType =
  | string
  | {
      multiType: string[];
    };

const resolveZodType = (schema: OpenApiSchemaObject): ResolvedZodType => {
  const schemaTypeValue = schema.type as unknown;

  // Handle array of types (OpenAPI 3.1+)
  if (Array.isArray(schemaTypeValue)) {
    // Filter out 'null' type as it's handled separately via nullable
    const nonNullTypes = schemaTypeValue
      .filter((t): t is string => isString(t))
      .filter((t) => t !== 'null' && possibleSchemaTypes.has(t));

    // If multiple types, return a special marker for union handling
    if (nonNullTypes.length > 1) {
      return { multiType: nonNullTypes };
    }

    // Single type
    const type = nonNullTypes[0];

    // Handle prefixItems for tuples
    if (type === 'array' && 'prefixItems' in schema) {
      return 'tuple';
    }

    return type;
  }

  // Handle single type value
  const type = isString(schemaTypeValue) ? schemaTypeValue : undefined;

  // TODO: if "prefixItems" exists and type is "array", then generate a "tuple"
  if (schema.type === 'array' && 'prefixItems' in schema) {
    return 'tuple';
  }

  // Infer type from const value when type is not explicitly specified
  if (!type && 'const' in schema) {
    const constValue = schema.const;
    if (isString(constValue)) return 'string';
    if (isNumber(constValue)) return 'number';
    if (isBoolean(constValue)) return 'boolean';
    if (constValue === null) return 'null';
  }

  return type ?? 'unknown';
};

// https://github.com/colinhacks/zod#coercion-for-primitives
const COERCIBLE_TYPES = new Set([
  'string',
  'number',
  'boolean',
  'bigint',
  'date',
]);

const zodMiniCoerceCall = (fn: string, args = '') =>
  `${PURE_COMMENT}zod.coerce.${fn}(${args})`;

// Unicode property escapes (`\p{...}`) require the `u` flag; without it they
// match the literal characters `p{...}`, so the generated validator silently
// rejects valid input (#3841). Only patterns that use them get the flag,
// leaving existing outputs unchanged.
const hasUnicodePropertyEscape = (pattern: string) =>
  /(^|[^\\])(?:\\\\)*\\[pP]\{/.test(pattern);

const buildRegExpLiteral = (pattern: string) => {
  const innerPattern = pattern.slice(
    pattern.startsWith('/') ? 1 : 0,
    pattern.endsWith('/') ? -1 : undefined,
  );
  const unicodeFlag = hasUnicodePropertyEscape(innerPattern) ? ", 'u'" : '';
  return `new RegExp('${jsStringLiteralEscape(innerPattern)}'${unicodeFlag})`;
};

/** Escapes string defaults for safe embedding in template literals. */
function formatDefaultValue(value: unknown): string {
  if (isString(value)) {
    return jsesc(value, { quotes: 'backtick', wrap: true });
  }
  if (Array.isArray(value)) {
    return `[${value
      .map((item) =>
        isString(item)
          ? jsesc(item, { quotes: 'backtick', wrap: true })
          : formatDefaultValue(item),
      )
      .join(', ')}]`;
  }
  return stringify(value) ?? 'null';
}

export interface ZodValidationSchemaDefinition {
  functions: [string, unknown][];
  consts: string[];
}

const minAndMaxTypes = new Set(['number', 'integer', 'string', 'array']);

/**
 * Whether a schema's default has to be emitted inline rather than hoisted into
 * a named const.
 *
 * Hoisting throws away the contextual type, which matters for two shapes: a
 * tuple widens to `T[]`, and an array of `$ref` items widens its literal
 * properties to their base types (#4023, #4024). Neither can be repaired after
 * the fact — unlike an array of `enum` items, where the hoisted const narrows
 * each element with `as const` and so must keep hoisting.
 *
 * The walk covers `properties` and `items`, so a tuple nested at any depth is
 * still found.
 *
 * @param schema Schema node to inspect, from anywhere in the document
 * @param seen Nodes already visited, guarding against a self-referential schema
 */
function needsInlineDefault(
  schema: unknown,
  seen = new Set<object>(),
): boolean {
  if (!schema || typeof schema !== 'object') {
    return false;
  }
  if (seen.has(schema)) {
    return false;
  }
  seen.add(schema);

  const node = schema as Record<string, unknown>;

  // A tuple anywhere below the default is enough on its own.
  if ('prefixItems' in node) {
    return true;
  }

  const items = node.items;
  if (items && typeof items === 'object') {
    // An array of `$ref` items cannot be narrowed here without resolving the
    // ref, so its literal types only survive inline.
    if ('$ref' in (items as Record<string, unknown>)) {
      return true;
    }
    if (needsInlineDefault(items, seen)) {
      return true;
    }
  }

  const properties = node.properties;
  if (properties && typeof properties === 'object') {
    return Object.values(properties as Record<string, unknown>).some((child) =>
      needsInlineDefault(child, seen),
    );
  }

  return false;
}

const removeReadOnlyProperties = (
  schema: OpenApiSchemaObject,
): OpenApiSchemaObject => {
  if (schema.properties && isObject(schema.properties)) {
    const filteredProperties: Record<string, OpenApiSchemaObject> = {};

    for (const [key, value] of Object.entries(schema.properties)) {
      if (isObject(value) && 'readOnly' in value && value.readOnly) {
        continue;
      }
      filteredProperties[key] = value as OpenApiSchemaObject;
    }

    return {
      ...(schema as Record<string, unknown>),
      properties: filteredProperties,
    };
  }
  if (schema.items && isObject(schema.items) && 'properties' in schema.items) {
    return {
      ...(schema as Record<string, unknown>),
      items: removeReadOnlyProperties(schema.items as OpenApiSchemaObject),
    };
  }
  return schema;
};

interface DateTimeOptions {
  offset?: boolean;
  local?: boolean;
  precision?: number;
}

interface TimeOptions {
  precision?: -1 | 0 | 1 | 2 | 3;
}

